const Correo=document.querySelector("#Correo"),Contraseña=document.querySelector("#Contraseña"),form=document.querySelector("#contenedor1"),notificacion=document.querySelector("#notificacion"),Home=document.querySelector("#Inventary");function mostrarNotificacion(o){const e=document.getElementById("notificacion");e.textContent=o,e.classList.remove("oculto"),e.classList.add("visible"),setTimeout(()=>{e.classList.remove("visible"),e.classList.add("oculto")},3e3)}form.addEventListener("submit",async o=>{if(o.preventDefault(),Contraseña.value&&Correo.value)try{const o={email:Correo.value,password:Contraseña.value};await axios.post("/api/login",o),window.location.pathname="/Casa"}catch(o){mostrarNotificacion("Correo o contraseña equivocados")}else mostrarNotificacion("No pueden estar vacios los inputs")}),Home.addEventListener("click",o=>{window.location.pathname="/"});